#include "HudMailbox.h"
#include <iostream>
#include <stdexcept>
using namespace playhub::hud;
static int checks;void Check(bool b,const char* text){++checks;if(!b)throw std::runtime_error(text);}
Pulse Make(){Pulse p;auto&a=p.authority;a.purpose=Purpose::PerformanceHud;a.generation=1;a.collectorEpoch=1;a.collectorLease=std::string(32,'a');a.ownerBuild=std::string(64,'b');a.appId=123;a.agentPid=10;a.agentBirth=11;a.gamePid=20;a.gameBirth=21;a.framePid=30;a.frameBirth=31;a.frameThread=40;a.sourceThread=50;a.session=1;a.gameWindow=60;a.wpfWindow=70;a.wpfInstance=80;a.gameRect={0,0,3840,2160};a.wpfRect={7,7,295,191};a.wpfClass=L"HwndWrapper[GamingMode;Playhub performance HUD;GUID]";p.enabled=p.ready=true;p.sequence=1;p.sampleTick=990;p.observedAt=1000;p.leaseExpiresAt=6000;return p;}
int main(){try{auto p=Make();Mailbox box;Check(box.Queue(1,p,1000),"first publisher reserves");box.begin.reset();auto newer=p;++newer.authority.generation;Check(!box.Queue(1,newer,1000),"dequeued slow Begin still owns reservation before publication");Check(box.Queue(3,p,1000),"Close can revoke before first publication");Check(!box.latest&&!box.begin&&box.close,"Close has priority over pending/active pulse");Check(!box.Queue(2,p,1000),"retired generation cannot pulse/reopen");box.close=false;box.Closed(1);Check(!box.admitted&&box.closedThrough==1,"Closed clears only exact reservation");Check(!box.Queue(1,p,1000),"old Begin cannot replay after Closed");Check(box.Queue(1,newer,1000),"fresh explicit Begin after confirmed cleanup");box.Closed(1);Check(box.admitted.has_value(),"late prior cleanup cannot drop new generation");auto foreign=newer;++foreign.authority.collectorEpoch;Check(!box.Queue(3,foreign,1000),"foreign collector cannot close current display");auto stale=newer;stale.sampleTick=500;Check(!box.Queue(2,stale,1000),"stale frame cannot renew data pulse");std::cout<<"{\"checks\":"<<checks<<",\"passed\":true,\"nativeCalls\":false}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
